    assertEquals(4, variables.size());
    assertEquals("F1_BT_io", variables.get(0).getFullName());
    assertEquals(DataType.SHORT, variables.get(0).getDataType());
    assertEquals("rows columns", variables.get(0).getDimensionsString());
