    assertEquals(5, elementMissingNodeAttributes.getLength());
    assertNotNull(elementMissingNodeAttributes.getNamedItem("grid"));
    assertEquals("1 km", elementMissingNodeAttributes.getNamedItem("grid").getNodeValue());
    assertNotNull(elementMissingNodeAttributes.getNamedItem("view"));
    assertEquals("Oblique", elementMissingNodeAttributes.getNamedItem("view").getNodeValue());
    assertNotNull(elementMissingNodeAttributes.getNamedItem("startTime"));
    assertEquals("2017-10-18T01:25:36.942504Z", elementMissingNodeAttributes.getNamedItem("startTime").getNodeValue());
    assertNotNull(elementMissingNodeAttributes.getNamedItem("stopTime"));
    assertEquals("2017-10-18T01:25:38.142447Z", elementMissingNodeAttributes.getNamedItem("stopTime").getNodeValue());
    assertNotNull(elementMissingNodeAttributes.getNamedItem("percentage"));
    assertEquals("0.285551", elementMissingNodeAttributes.getNamedItem("percentage").getNodeValue());
