    assertNotNull(elementMissingNodeAttributes.getNamedItem("percentage"));
    assertEquals("0.114220", elementMissingNodeAttributes.getNamedItem("percentage").getNodeValue());
    final NodeList elementMissingNodeChildNodes = childNodes.item(5).getChildNodes();
