    subsetDef.setSubsetRegion(new PixelSubsetRegion(0, 0, product.getSceneRasterWidth(), 10, 0));
    Product subsetProduct = ProductSubsetBuilder.createProductSubset(product, subsetDef, "s", "s");
    BowtiePixelGeoCoding bowtiePixelGeoCoding_aux = (BowtiePixelGeoCoding) subsetProduct.getSceneGeoCoding();
    assertEquals("for y=" + 0 + " scanlineOffset", 0, bowtiePixelGeoCoding_aux.getScanlineOffset());
    ProductSubsetDef subsetDef = new ProductSubsetDef();
    subsetDef.setSubsetRegion(new PixelSubsetRegion(0, 0, product.getSceneRasterWidth(), 30, 0));
