// Test prefix
public void testScanLineOffset() throws URISyntaxException, IOException {
    Product product = ProductIO.readProduct(new File(getClass().getResource("bowtiepixelgeocoding_test_product.L2_sub").toURI()));
    // latitude values increasing
    BowtiePixelGeoCoding bowtiePixelGeoCoding = (BowtiePixelGeoCoding) product.getSceneGeoCoding();
    assertEquals(0, bowtiePixelGeoCoding.getScanlineOffset());
    // flipped product, latitude values decreasing
    Product flippedProduct = ProductFlipper.createFlippedProduct(product, ProductFlipper.FLIP_BOTH, "f", "f");
    bowtiePixelGeoCoding = (BowtiePixelGeoCoding) flippedProduct.getSceneGeoCoding();
    assertEquals(0, bowtiePixelGeoCoding.getScanlineOffset());
    ProductSubsetDef subsetDef = new ProductSubsetDef();
    subsetDef.setSubsetRegion(new PixelSubsetRegion(0, 0, product.getSceneRasterWidth(), 10, 0));
    Product subsetProduct = ProductSubsetBuilder.createProductSubset(product, subsetDef, "s", "s");
    BowtiePixelGeoCoding bowtiePixelGeoCoding_aux = (BowtiePixelGeoCoding) subsetProduct.getSceneGeoCoding();
    assertEquals("for y=" + 0 + " scanlineOffset", 0, bowtiePixelGeoCoding_aux.getScanlineOffset());
    ProductSubsetDef subsetDef = new ProductSubsetDef();
    subsetDef.setSubsetRegion(new PixelSubsetRegion(0, 0, product.getSceneRasterWidth(), 30, 0));
    Product subsetProduct = ProductSubsetBuilder.createProductSubset(product, subsetDef, "s", "s");
    BowtiePixelGeoCoding bowtiePixelGeoCoding_aux = (BowtiePixelGeoCoding) subsetProduct.getSceneGeoCoding();
    assertEquals("for y=" + 0 + " scanlineOffset", 0, bowtiePixelGeoCoding_aux.getScanlineOffset());
    ProductSubsetDef subsetDef = new ProductSubsetDef();
    subsetDef.setSubsetRegion(new PixelSubsetRegion(0, 1, product.getSceneRasterWidth(), 30, 0));
    Product subsetProduct = ProductSubsetBuilder.createProductSubset(product, subsetDef, "s", "s");
    BowtiePixelGeoCoding bowtiePixelGeoCoding_aux = (BowtiePixelGeoCoding) subsetProduct.getSceneGeoCoding();
    assertEquals("for y=" + 1 + " scanlineOffset", 9, bowtiePixelGeoCoding_aux.getScanlineOffset());
    ProductSubsetDef subsetDef = new ProductSubsetDef();
    subsetDef.setSubsetRegion(new PixelSubsetRegion(0, 2, product.getSceneRasterWidth(), 30, 0));
    Product subsetProduct = ProductSubsetBuilder.createProductSubset(product, subsetDef, "s", "s");
    BowtiePixelGeoCoding bowtiePixelGeoCoding_aux = (BowtiePixelGeoCoding) subsetProduct.getSceneGeoCoding();
    assertEquals("for y=" + 2 + " scanlineOffset", 8, bowtiePixelGeoCoding_aux.getScanlineOffset());
    ProductSubsetDef subsetDef = new ProductSubsetDef();
    subsetDef.setSubsetRegion(new PixelSubsetRegion(0, 3, product.getSceneRasterWidth(), 30, 0));
    Product subsetProduct = ProductSubsetBuilder.createProductSubset(product, subsetDef, "s", "s");
    BowtiePixelGeoCoding bowtiePixelGeoCoding_aux = (BowtiePixelGeoCoding) subsetProduct.getSceneGeoCoding();
    assertEquals("for y=" + 3 + " scanlineOffset", 7, bowtiePixelGeoCoding_aux.getScanlineOffset());
    ProductSubsetDef subsetDef = new ProductSubsetDef();
    subsetDef.setSubsetRegion(new PixelSubsetRegion(0, 4, product.getSceneRasterWidth(), 30, 0));
    Product subsetProduct = ProductSubsetBuilder.createProductSubset(product, subsetDef, "s", "s");
    BowtiePixelGeoCoding bowtiePixelGeoCoding_aux = (BowtiePixelGeoCoding) subsetProduct.getSceneGeoCoding();
    assertEquals("for y=" + 4 + " scanlineOffset", 6, bowtiePixelGeoCoding_aux.getScanlineOffset());
