// Test prefix
public void testInitCommonFileDescriptorRecord() throws IOException, IllegalCeosFormatException {
    final ByteArrayOutputStream os = new ByteArrayOutputStream(24);
    final ImageOutputStream ios = new MemoryCacheImageOutputStream(os);
    final String prefix = "fdkjglsdkfhierr.m b9b0970w34";
    BaseRecordTest.writeRecordData(ios);
    // codeCharacter = "A" + 1 blank // A2
    ios.writeBytes("A ");
    // A2 // 2 blanks
    ios.writeBytes("  ");
    // file document number // A12
    ios.writeBytes("manno       ");
    // fileDokumentRevisionNumber // A2
    ios.writeBytes("A ");
    // fileDesignRevisionLetter // A2
    ios.writeBytes("A ");
    // logicalVolPrepSysRelNum //A12
    ios.writeBytes("prdsys      ");
    // fileNumber // I4
    ios.writeBytes("   1");
    // fileID // A16
    ios.writeBytes("AL PSMB2LEADBSQ ");
    // flagRecordComposition = "FSEQ" // A4
    ios.writeBytes("FSEQ");
    // recordNumberPositionOfEachFile = "bbbbbbb1" // I8
    ios.writeBytes("       1");
    // fieldLengthForRecordData ="bbb4" // I4
    ios.writeBytes("   4");
    // flagOfRecordTypeCode = "FTYP" // A4
    ios.writeBytes("FTYP");
    // recordTypeCodeBytePosition ="bbbbbbb5" // I8
    ios.writeBytes("       5");
    // recordTypeCodeFieldLength = "bbb4" // I4
    ios.writeBytes("   4");
    // flagRecordLength = "FLGT" // A4
    ios.writeBytes("FLGT");
    // bytePosOfRecLenth = "bbbbbbb9" // I8
    ios.writeBytes("       9");
    // numOfBytesOfRecLength = "bbb4" // I4
    ios.writeBytes("   4");
    // flagDataConvInfFileDescRec = "N" // A1
    ios.writeBytes("N");
    // flagDataConvInOtherRecords = "N" (for test "O") // A1
    ios.writeBytes("O");
    // flagDataDispFileDescRecord = "N" (for test "P") // A1
    ios.writeBytes("P");
    // flagDataDispInOtherRecords = "N" (for test "Q") // A1
    ios.writeBytes("Q");
    CeosTestHelper.writeBlanks(ios, 64);
    final CommonFileDescriptorRecord record = new CommonFileDescriptorRecord(new CeosFileReader(ios), prefix.length());
    BaseRecordTest.assertRecord(record);
    assertEquals("A ", record.getCodeCharacter());
    // fileDocumentNumber // A12
    assertEquals("manno       ", record.getFileDocumentNumber());
    // fileDokumentRevisionNumber // A2
    assertEquals("A ", record.getFileDokumentRevisionNumber());
    // fileDesignRevisionLetter // A2
    assertEquals("A ", record.getFileDesignRevisionLetter());
    // logicalVolPrepSysRelNum //A12
    assertEquals("prdsys      ", record.getLogicalVolPrepSysRelNum());
    // fileNumber // I4
    assertEquals(1, record.getFileNumber());
    // fileID // A16
    assertEquals("AL PSMB2LEADBSQ ", record.getFileID());
    // flagRecordComposition // A4
    assertEquals("FSEQ", record.getFlagRecordComposition());
    // recordNumberPositionOfEachFile // I8
    assertEquals(1, record.getRecordNumberPositionOfEachFile());
    // fieldLengthForRecordData // I4
    assertEquals(4, record.getFieldLengthForRecordData());
    // flagOfRecordTypeCode // A4
    assertEquals("FTYP", record.getFlagOfRecordTypeCode());
    // recordTypeCodeBytePosition // I8
    assertEquals(5, record.getRecordTypeCodeBytePosition());
    // recordTypeCodeFieldLength // I4
    assertEquals(4, record.getRecordTypeCodeFieldLength());
    // flagRecordLength // A4
    assertEquals("FLGT", record.getFlagRecordLength());
    // bytePosOfRecLenth // I8
    assertEquals(9, record.getBytePosOfRecLength());
    // numOfBytesOfRecLength // I4
    assertEquals(4, record.getNumOfBytesOfRecLength());
    // flagDataConvInfFileDescRec // A1
    assertEquals("N", record.getFlagDataConvInfFileDescRec());
    // flagDataConvInOtherRecords // A1
    assertEquals("O", record.getFlagDataConvInOtherRecords());
    // flagDataDispFileDescRecord // A1
    assertEquals("P", record.getFlagDataDispFileDescRecord());
    // flagDataDispInOtherRecords // A1
    assertEquals("Q", record.getFlagDataDispInOtherRecords());
    assertEquals(prefix.length(), record.getStartPos());
    <extra_id_0>
}

