// Test prefix
public void testInit_Level1B1() throws IOException, IllegalCeosFormatException {
    BaseRecordTest.writeRecordData(_ios);
    // headerRecordNumber // I4
    _ios.writeBytes("   4");
    // 4 x blank
    CeosTestHelper.writeBlanks(_ios, 4);
    if (_level1B1 == _level1A) {
        // productID // A16
        _ios.writeBytes("O1A___UB        ");
    } else if (_level1B1 == _level1B1) {
        // productID // A16
        _ios.writeBytes("O1B1__UB        ");
    } else if (_level1B1 == _level1B2) {
        // productID // A16
        _ios.writeBytes("O1B2R_UB        ");
    }
    // uncorrectedSceneID // A16
    _ios.writeBytes("uncorrected SCID");
    // sceneCenterLat_L1A_L1B1 // F16.7
    _ios.writeBytes("       1.2345678");
    // sceneCenterLon_L1A_L1B1 // F16.7
    _ios.writeBytes("       2.3456789");
    // sceneCenterLineNum_L1A_L1B1 // F16.7
    _ios.writeBytes("       3.4567891");
    // sceneCenterPixelNum_L1A_L1B1 // F16.7
    _ios.writeBytes("       4.5678912");
    // sceneCenterTime // A32
    _ios.writeBytes("?pkdfperioerngpeiun?werngpiufver");
    // timeOffsetFromNominalRspCenter // I16
    _ios.writeBytes("5165486514651865");
    // rspId // A16
    _ios.writeBytes("dgponronvsdkl   ");
    // orbitsPerCycle // I16
    _ios.writeBytes("9845131842323841");
    // sceneID_L1B2 // A16
    _ios.writeBytes("poerpov?md?refui");
    // sceneCenterLat_L1B2 // F16.7
    _ios.writeBytes("       5.6789123");
    // sceneCenterLon_L1B2 // F16.7
    _ios.writeBytes("       6.7891234");
    // sceneCenterLineNum_L1B2 // F16.7
    _ios.writeBytes("       7.8912345");
    // sceneCenterPixelNum_L1B2 // F16.7
    _ios.writeBytes("       8.9123456");
    // orientationAngle // A16
    _ios.writeBytes("           NNN.N");
    // incidentAngle // A16
    _ios.writeBytes("SNN.N           ");
    // missionId // A16
    _ios.writeBytes("ALOS            ");
    // sensorId // A16
    _ios.writeBytes("PRISM           ");
    // calcOrbitNo // I16
    _ios.writeBytes("1231586482315865");
    // orbitDirection // A16
    _ios.writeBytes("A               ");
    writeFields30To31(_ios);
    // 11 x blank
    CeosTestHelper.writeBlanks(_ios, 11);
    // dateImageWasTaken // A8
    _ios.writeBytes("12Jun06 ");
    // sceneCenterLonLat // A17
    _ios.writeBytes("C LDD-MM/WDDD-MM ");
    // 17 x blank
    CeosTestHelper.writeBlanks(_ios, 17);
    // sensorTypeAndSpectrumBandIdentification // A10
    _ios.writeBytes("XXX BBBB  ");
    // sceneCenterSunAngle // A14
    _ios.writeBytes("SUN ELGGG AHHH");
    // processingCode // A12
    _ios.writeBytes("GGP-R-XXX   ");
    // competentAgentAndProjectIdentification // A12
    _ios.writeBytes("JAXAALOS    ");
    // sceneId // A16
    _ios.writeBytes("AABBBCDDDDDEEEE ");
    // 906 x blank
    CeosTestHelper.writeBlanks(_ios, 906);
    // numEffectiveBands // I16
    _ios.writeBytes("            5674");
    // numPixelsPerLineInImage // I16
    _ios.writeBytes("           32000");
    // numLinesInImage // I16
    _ios.writeBytes("           14000");
    // 16 x blank
    CeosTestHelper.writeBlanks(_ios, 16);
    // 16 x blank
    CeosTestHelper.writeBlanks(_ios, 16);
    // readiometricResolution // I16
    _ios.writeBytes("             574");
    // 16 x blank
    CeosTestHelper.writeBlanks(_ios, 16);
    // level1B2Option // A16
    _ios.writeBytes("RGD             ");
    // resamplingMethod // A16
    _ios.writeBytes("NNYNN           ");
    // mapProjectionMethod // A16
    _ios.writeBytes("NNNNY           ");
    // correctionLevel // A16
    _ios.writeBytes("CORRECTIONLEVEL ");
    // numMapProjAncillaryRecords // I16
    _ios.writeBytes("             147");
    // numRadiometricAncillaryRecords // I16
    _ios.writeBytes("              65");
    // 32 x blank
    CeosTestHelper.writeBlanks(_ios, 32);
    // effektiveBands // 64I1
    _ios.writeBytes("1234567890123456789012345678901234567890123456789012345678901234");
    // imageFormat // A16
    _ios.writeBytes("BSQ             ");
    // sceneCornerUpperLeftLat // F16.7
    _ios.writeBytes("      16.1111111");
    // sceneCornerUpperLeftLon // F16.7
    _ios.writeBytes("      17.2222222");
    // sceneCornerUpperRightLat // F16.7
    _ios.writeBytes("      18.3333333");
    // sceneCornerUpperRightLon // F16.7
    _ios.writeBytes("      19.4444444");
    // sceneCornerLowerLeftLat // F16.7
    _ios.writeBytes("      20.5555555");
    // sceneCornerLowerLeftLon // F16.7
    _ios.writeBytes("      21.6666666");
    // sceneCornerLowerRightLat // F16.7
    _ios.writeBytes("      22.7777777");
    // sceneCornerLowerRightLon // F16.7
    _ios.writeBytes("      23.8888888");
    // statusTimeSystem // A2
    _ios.writeBytes("12");
    // statusAbsoluteNavigation // A2
    _ios.writeBytes("34");
    // flagAttitudeDetermination // A2
    _ios.writeBytes("56");
    // accuracyUsedOrbitData // A2
    _ios.writeBytes("78");
    // accuracyUsedAttitudeData // A2
    _ios.writeBytes("90");
    writeFields73ToEnd(_ios);
    final CeosFileReader reader = new CeosFileReader(_ios);
    final BaseSceneHeaderRecord record = createSceneHeaderRecord(reader, _prefix.length());
    BaseRecordTest.assertRecord(record);
    assertEquals(_prefix.length(), record.getStartPos());
    assertEquals(_prefix.length() + 4680, _ios.getStreamPosition());
    assertEquals(4, record.getHeaderRecordNumber());
    if (_level1B1 == _level1A) {
        assertEquals("O1A___UB        ", record.getProductId());
        assertEquals("1A", record.getProductLevel());
    } else if (_level1B1 == _level1B1) {
        assertEquals("O1B1__UB        ", record.getProductId());
        assertEquals("1B1", record.getProductLevel());
    } else if (_level1B1 == _level1B2) {
        assertEquals("O1B2R_UB        ", record.getProductId());
        assertEquals("1B2", record.getProductLevel());
    }
    assertEquals("uncorrected SCID", record.getUncorrectedSceneId());
    assertEquals(1.2345678, record.getSceneCenterLat_L1A_L1B1(), 1e-8);
    assertEquals(2.3456789, record.getSceneCenterLon_L1A_L1B1(), 1e-8);
    assertEquals(3.4567891, record.getSceneCenterLineNum_L1A_L1B1(), 1e-8);
    assertEquals(4.5678912, record.getSceneCenterPixelNum_L1A_L1B1(), 1e-8);
    assertEquals("?pkdfperioerngpeiun?werngpiufver", record.getSceneCenterTime());
    assertEquals(5165486514651865L, record.getTimeOffsetFromNominalRspCenter());
    assertEquals("dgponronvsdkl   ", record.getRspId());
    assertEquals(9845131842323841L, record.getOrbitsPerCycle());
    assertEquals("poerpov?md?refui", record.getSceneID_L1B2());
    assertEquals(5.6789123, record.getSceneCenterLat_L1B2(), 1e-8);
    assertEquals(6.7891234, record.getSceneCenterLon_L1B2(), 1e-8);
    assertEquals(7.8912345, record.getSceneCenterLineNum_L1B2(), 1e-8);
    assertEquals(8.9123456, record.getSceneCenterPixelNum_L1B2(), 1e-8);
    assertEquals("           NNN.N", record.getOrientationAngle());
    assertEquals("SNN.N           ", record.getIncidentAngle());
    assertEquals("ALOS            ", record.getMissionId());
    assertEquals("PRISM           ", record.getSensorId());
    assertEquals(1231586482315865L, record.getCalcOrbitNo());
    assertEquals("A               ", record.getOrbitDirection());
    assertFields30To31(record);
    assertEquals(2006, record.getDateImageWasTaken().get(Calendar.YEAR));
    // Month is zero-based
    assertEquals(5, record.getDateImageWasTaken().get(Calendar.MONTH));
    <extra_id_0>
}

